package vibelangfuzz

// VIP-7: tagged members and async-match jumps quote the landed chapter.
func dataTaggedMembersRules() []dataRule {
	return []dataRule{
		{name: "tagged-symbol-missing", chapter: "004-match.md", quote: "a `unique symbol`, or a union of those.", source: "const A:unique symbol=Symbol();const B:unique symbol=Symbol();function f(s:{_tag:typeof A}|{_tag:typeof B}){return match(s){when if(false):0;}}", code: "EK4701", owner: "cov-match"},
		{name: "tagged-interface-missing", chapter: "004-match.md", quote: "it is an object, interface or class instance", source: "interface A{_tag:\"A\"};interface B{_tag:\"B\"};function f(s:A|B){return match(s){when {_tag:\"A\"}:1;}}", code: "EK4701", owner: "cov-match"},
		{name: "tagged-class-missing", chapter: "004-match.md", quote: "it is an object, interface or class instance", source: "class A{readonly _tag=\"A\" as const};class B{readonly _tag=\"B\" as const};function f(s:A|B){return match(s){when {_tag:\"A\"}:1;}}", code: "EK4701", owner: "cov-match"},
		{name: "tagged-shared-bare", chapter: "004-match.md", quote: "Members that share a tag are covered one at a time, and one left uncovered stays uncovered.", source: "type S={_tag:\"A\";x:number}|{_tag:\"A\";y:number};function f(s:S){return match(s){when {_tag:\"A\"}:1;}}", code: "", owner: "vip-match"},
		{name: "tagged-shared-required", chapter: "004-match.md", quote: "Members that share a tag are covered one at a time, and one left uncovered stays uncovered.", source: "type S={_tag:\"A\";x:number}|{_tag:\"A\";y:number};function f(s:S){return match(s){when {_tag:\"A\",let x}:x;}}", code: "EK4701", owner: "vip-match"},
		{name: "tagged-shared-required-both", chapter: "004-match.md", quote: "Members that share a tag are covered one at a time, and one left uncovered stays uncovered.", source: "type S={_tag:\"A\";x:number}|{_tag:\"A\";y:number};function f(s:S){return match(s){when {_tag:\"A\",x:let x}:x;when {_tag:\"A\",y:let y}:y;}}", code: "", owner: "impl-hunt-data"},
		{name: "tagged-shared-cases-complete", chapter: "004-match.md", quote: "Members that share a tag are covered one at a time, and one left uncovered stays uncovered.", source: "type S={_tag:\"A\"|\"B\";x:number}|{_tag:\"A\"|\"B\";y:string};function f(s:S){return match(s){when {_tag:\"A\"}:1;when {_tag:\"B\"}:2;}}", code: "", owner: "impl-hunt-data"},
		{name: "tagged-shared-cases-missing", chapter: "004-match.md", quote: "Members that share a tag are covered one at a time, and one left uncovered stays uncovered.", source: "type S={_tag:\"A\"|\"B\";x:number}|{_tag:\"A\"|\"B\";y:string};function f(s:S){return match(s){when {_tag:\"A\"}:1;}}", code: "EK4701", owner: "impl-hunt-data"},
		{name: "tagged-shared-cases-guarded", chapter: "004-match.md", quote: "Members that share a tag are covered one at a time, and one left uncovered stays uncovered.", source: "type S={_tag:\"A\"|\"B\";x:number}|{_tag:\"A\"|\"B\";y:string};function f(s:S,g:boolean){return match(s){when {_tag:\"A\"} and if(g):1;when {_tag:\"B\"}:2;}}", code: "EK4701", owner: "impl-hunt-data"},
		{name: "tagged-shared-mixed-missing", chapter: "004-match.md", quote: "Members that share a tag are covered one at a time, and one left uncovered stays uncovered.", source: "function f(s:{_tag:\"A\"|\"B\";x:number}|{_tag:\"C\"}){return match(s){when {_tag:\"A\"}:1;when {_tag:\"C\"}:3;}}", code: "EK4701", owner: "impl-hunt-data"},
		{name: "tagged-string-enum-complete", chapter: "004-match.md", quote: "a string, number, bigint, boolean, enum, `null` or `undefined` literal, a `unique symbol`, or a union of those.", source: "enum E{A=\"a\",B=\"b\"};function f(s:{_tag:E;v:number}){return match(s){when {_tag:E.A}:1;when {_tag:E.B}:2;}}", code: "", owner: "impl-hunt-data"},
		{name: "tagged-string-enum-missing", chapter: "004-match.md", quote: "a string, number, bigint, boolean, enum, `null` or `undefined` literal, a `unique symbol`, or a union of those.", source: "enum E{A=\"a\",B=\"b\"};function f(s:{_tag:E;v:number}){return match(s){when {_tag:E.A}:1;}}", code: "EK4701", owner: "impl-hunt-data"},
		{name: "tagged-unique-symbol-complete", chapter: "004-match.md", quote: "a string, number, bigint, boolean, enum, `null` or `undefined` literal, a `unique symbol`, or a union of those.", source: "const A:unique symbol=Symbol();const B:unique symbol=Symbol();function f(s:{_tag:typeof A}|{_tag:typeof B}){return match(s){when {_tag:A}:1;when {_tag:B}:2;}}", code: "", owner: "impl-hunt-data"},
		{name: "tagged-unique-symbol-missing", chapter: "004-match.md", quote: "a string, number, bigint, boolean, enum, `null` or `undefined` literal, a `unique symbol`, or a union of those.", source: "const A:unique symbol=Symbol();const B:unique symbol=Symbol();function f(s:{_tag:typeof A}|{_tag:typeof B}){return match(s){when {_tag:A}:1;}}", code: "EK4701", owner: "impl-hunt-data"},
		{name: "tagged-union-missing", chapter: "004-match.md", quote: "Each of those literals is a case of the member", source: "function f(s:{_tag:\"A\"|\"B\"}|{_tag:\"C\"}){return match(s){when {_tag:\"A\"}:1;when {_tag:\"C\"}:3;}}", code: "EK4701", owner: "vip-match"},
		{name: "tagged-union-complete", chapter: "004-match.md", quote: "Each of those literals is a case of the member", source: "function f(s:{_tag:\"A\"|\"B\"}|{_tag:\"C\"}){return match(s){when {_tag:\"A\"}:1;when {_tag:\"B\"}:2;when {_tag:\"C\"}:3;}}", code: "", owner: "vip-match"},
		{name: "tagged-optional-missing", chapter: "004-match.md", quote: "an optional `_tag` has the case `undefined`.", source: "function f(s:{_tag?:\"A\"}|{_tag:\"B\"}){return match(s){when {_tag:\"A\"}:1;when {_tag:\"B\"}:2;}}", code: "EK4701", owner: "vip-match"},
		{name: "tagged-optional-object-undefined", chapter: "004-match.md", quote: "The `undefined` case of an optional `_tag` is covered only by a bare binding", source: "function f(s:{_tag?:\"A\"}){return match(s){when {_tag:\"A\"}:1;when {_tag:undefined}:0;}}", code: "EK4701", owner: "vip-match"},
		{name: "tagged-optional-binding", chapter: "004-match.md", quote: "The `undefined` case of an optional `_tag` is covered only by a bare binding", source: "function f(s:{_tag?:\"A\"}){return match(s){when let x:1;}}", code: "", owner: "vip-match"},
		{name: "tagged-number-missing", chapter: "004-match.md", quote: "a string, number, bigint, boolean, enum, `null` or `undefined` literal,", source: "function f(s:{_tag:1|2}){return match(s){when {_tag:1}:1;}}", code: "EK4701", owner: "vip-match"},
		{name: "tagged-bigint-missing", chapter: "004-match.md", quote: "a string, number, bigint, boolean, enum, `null` or `undefined` literal,", source: "function f(s:{_tag:1n|2n}){return match(s){when {_tag:1n}:1;}}", code: "EK4701", owner: "vip-match"},
		{name: "tagged-boolean-missing", chapter: "004-match.md", quote: "a string, number, bigint, boolean, enum, `null` or `undefined` literal,", source: "function f(s:{_tag:true|false}){return match(s){when {_tag:true}:1;}}", code: "EK4701", owner: "vip-match"},
		{name: "tagged-null-missing", chapter: "004-match.md", quote: "a string, number, bigint, boolean, enum, `null` or `undefined` literal,", source: "function f(s:{_tag:null|1}){return match(s){when {_tag:1}:1;}}", code: "EK4701", owner: "vip-match"},
		{name: "tagged-undefined-missing", chapter: "004-match.md", quote: "a string, number, bigint, boolean, enum, `null` or `undefined` literal,", source: "function f(s:{_tag:undefined|1}){return match(s){when {_tag:1}:1;}}", code: "EK4701", owner: "vip-match"},
		{name: "tagged-enum-missing", chapter: "004-match.md", quote: "a string, number, bigint, boolean, enum, `null` or `undefined` literal,", source: "enum E{A,B};function f(s:{_tag:E}){return match(s){when {_tag:E.A}:1;}}", code: "EK4701", owner: "vip-match"},
		{name: "tagged-literals-complete", chapter: "004-match.md", quote: "a string, number, bigint, boolean, enum, `null` or `undefined` literal,", source: "function f(s:{_tag:1}|{_tag:true}|{_tag:null}){return match(s){when {_tag:1}:1;when {_tag:true}:2;when {_tag:null}:3;}}", code: "", owner: "vip-match"},
		{name: "tagged-number-complete", chapter: "004-match.md", quote: "a string, number, bigint, boolean, enum, `null` or `undefined` literal,", source: "function f(s:{_tag:1|2}){return match(s){when {_tag:1}:1;when {_tag:2}:2;}}", code: "", owner: "vip-match"},
		{name: "tagged-bigint-complete", chapter: "004-match.md", quote: "a string, number, bigint, boolean, enum, `null` or `undefined` literal,", source: "function f(s:{_tag:1n|2n}){return match(s){when {_tag:1n}:1;when {_tag:2n}:2;}}", code: "", owner: "vip-match"},
		{name: "tagged-boolean-complete", chapter: "004-match.md", quote: "a string, number, bigint, boolean, enum, `null` or `undefined` literal,", source: "function f(s:{_tag:true|false}){return match(s){when {_tag:true}:1;when {_tag:false}:2;}}", code: "", owner: "vip-match"},
		{name: "tagged-enum-complete", chapter: "004-match.md", quote: "a string, number, bigint, boolean, enum, `null` or `undefined` literal,", source: "enum E{A,B};function f(s:{_tag:E}){return match(s){when {_tag:E.A}:1;when {_tag:E.B}:2;}}", code: "", owner: "vip-match"},
		{name: "tagged-undefined-complete", chapter: "004-match.md", quote: "a string, number, bigint, boolean, enum, `null` or `undefined` literal,", source: "function f(s:{_tag:undefined}){return match(s){when {_tag:undefined}:0;}}", code: "", owner: "vip-match"},
		{name: "tagged-wide-disabled", chapter: "004-match.md", quote: "A `_tag` of any other type, such as `string` or a template type, is not tagged", source: "function f(s:{_tag:\"A\"}|{_tag:string}){return match(s){when {_tag:\"A\"}:1;}}", code: "", owner: "vip-match"},
		{name: "tagged-template-disabled", chapter: "004-match.md", quote: "A `_tag` of any other type, such as `string` or a template type, is not tagged", source: "function f(s:{_tag:`A_${number}`}){return match(s){when {_tag:\"A_1\"}:1;}}", code: "", owner: "vip-match"},
		{name: "tagged-other-discriminant-checked", chapter: "004-match.md", quote: "A match without `default` over objects with literal-typed discriminant fields other than `_tag` reports error `EK4701` when cases remain.", source: "function f(s:{kind:\"A\"}|{kind:\"B\"}){return match(s){when {kind:\"A\"}:1;}}", code: "EK4701", owner: "vip-match"},
		{name: "tagged-optional-payload-missing", chapter: "004-match.md", quote: "`\"x\" in s` removes a member from its false branch only where `x` is required.", source: "function f(s:{_tag:\"A\";x?:number}|{_tag:\"B\"}){return match(s){when {_tag:\"A\",x}:1;when {_tag:\"B\"}:2;}}", code: "EK4701", owner: "vip-match"},
		{name: "async-match-return-rejected", chapter: "004-match.md", quote: "a `return` in it, and a `break` or `continue` whose target is outside it, are syntax errors.", source: "function f(){return async match(1){default:do{return 7};}}", code: "EK0706", owner: "conf-auto-async-match-lowering"},
		{name: "async-match-break-rejected", chapter: "004-match.md", quote: "a `return` in it, and a `break` or `continue` whose target is outside it, are syntax errors.", source: "function f(){while(true){const x=async match(1){default:do{break};};}}", code: "EK0706", owner: "conf-auto-async-match-lowering"},
		{name: "async-match-continue-rejected", chapter: "004-match.md", quote: "a `return` in it, and a `break` or `continue` whose target is outside it, are syntax errors.", source: "function f(){for(let i=0;i<1;i++){const x=async match(1){default:do{continue};};}}", code: "EK0706", owner: "conf-auto-async-match-lowering"},
	}
}

